func ptrCorrection(p unsafe.Pointer, c int32) any {
	r := (*aicorrection.Correction)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Task))
	case 4:
		return (*string)(unsafe.Pointer(&r.SourceType))
	case 5:
		return (*string)(unsafe.Pointer(&r.SourceID))
	case 6:
		return (**string)(unsafe.Pointer(&r.DocumentID))
	case 7:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 8:
		return (*string)(unsafe.Pointer(&r.SubjectID))
	case 9:
		return (*string)(unsafe.Pointer(&r.CapturedByID))
	case 10:
		return &r.DocumentKind
	case 11:
		return &r.DocumentFingerprint
	case 12:
		return &r.ExtractionModel
	case 13:
		return (**string)(unsafe.Pointer(&r.ExtractionProviderID))
	case 14:
		return &r.PredictedConfidence
	case 15:
		return &r.Predicted
	case 16:
		return &r.Confirmed
	case 17:
		return &r.FieldResults
	case 18:
		return (*int64)(unsafe.Pointer(&r.ScoredCount))
	case 19:
		return (*int64)(unsafe.Pointer(&r.CorrectCount))
	case 20:
		return (*int64)(unsafe.Pointer(&r.CorrectedCount))
	case 21:
		return (*int64)(unsafe.Pointer(&r.MissedCount))
	case 22:
		return (*int64)(unsafe.Pointer(&r.UnconfirmedCount))
	case 23:
		return (*int64)(unsafe.Pointer(&r.UnscoredCount))
	case 24:
		return &r.CapturedAt
	case 25:
		return &r.Version
	case 26:
		return &r.CreatedAt
	case 27:
		return &r.UpdatedAt
	}
	return nil
}

func valueCorrection(p unsafe.Pointer, c int32) any {
	r := (*aicorrection.Correction)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Task)
	case 4:
		return string(r.SourceType)
	case 5:
		return string(r.SourceID)
	case 6:
		if r.DocumentID == nil {
			return nil
		}
		return string(*r.DocumentID)
	case 7:
		return string(r.SubjectType)
	case 8:
		return string(r.SubjectID)
	case 9:
		return string(r.CapturedByID)
	case 10:
		if r.DocumentKind == "" {
			return nil
		}
		return r.DocumentKind
	case 11:
		if r.DocumentFingerprint == "" {
			return nil
		}
		return r.DocumentFingerprint
	case 12:
		if r.ExtractionModel == "" {
			return nil
		}
		return r.ExtractionModel
	case 13:
		if r.ExtractionProviderID == nil {
			return nil
		}
		return string(*r.ExtractionProviderID)
	case 14:
		return r.PredictedConfidence
	case 15:
		if r.Predicted == nil {
			return nil
		}
		return *r.Predicted
	case 16:
		if r.Confirmed == nil {
			return nil
		}
		return *r.Confirmed
	case 17:
		if r.FieldResults == nil {
			return keel.EmptyJSONArray
		}
		return r.FieldResults
	case 18:
		return int64(r.ScoredCount)
	case 19:
		return int64(r.CorrectCount)
	case 20:
		return int64(r.CorrectedCount)
	case 21:
		return int64(r.MissedCount)
	case 22:
		return int64(r.UnconfirmedCount)
	case 23:
		return int64(r.UnscoredCount)
	case 24:
		return r.CapturedAt
	case 25:
		return r.Version
	case 26:
		return r.CreatedAt
	case 27:
		return r.UpdatedAt
	}
	return nil
}

